Local Ltac wsfeed := first [ assumption | PMK.rk | PMK.gmem | first [unfold PQTSW2LP.aligned | unfold PQTSW2DP.aligned]; first [assumption | lia] | PMK.sc ].
Local Ltac splits H := lazymatch type of H with _ /\ _ => let H1 := fresh "Cj" in let H2 := fresh "Cj" in destruct H as [H1 H2]; splits H1; splits H2 | _ => idtac end.
Local Ltac lregs_ks KS X2 X8 X9 X18 X19 X20 X21 KP :=
  split; [rewrite (KS 2%nat) by PMK.inl; exact X2|]; split; [rewrite (KS 8%nat) by PMK.inl; exact X8|]; split; [rewrite (KS 9%nat) by PMK.inl; exact X9|];
  split; [rewrite (KS 18%nat) by PMK.inl; exact X18|]; split; [rewrite (KS 19%nat) by PMK.inl; exact X19|]; split; [rewrite (KS 20%nat) by PMK.inl; exact X20|];
  split; [rewrite (KS 21%nat) by PMK.inl; exact X21|];
  let kk := fresh "kk" in let Hk := fresh "Hkk" in intros kk Hk; rewrite (KS kk) by (cbn in Hk; repeat (destruct Hk as [<-|Hk]; [PMK.inl|]); destruct Hk); apply KP; exact Hk.

