(* [comment removed for export] *)
Lemma newR_call fx R M model (LBc : list (Z * Z)) (cr : credit) (sp' r : Z) :
  hi_heap HI LBc cr M (m_vmmaps model) -> model_but_vm model0 model -> mem_ok M -> incl LB LBc -> 1 <= fst cr -> 2 ^ 20 <= snd cr ->
  getr R (reg 10) = Z_to_bv 64 64 -> getr R (reg 1) = Z_to_bv 64 r -> L5.ra_ok r -> getr R (reg 2) = Z_to_bv 64 sp' -> getr R (reg 4) = getr R0 (reg 4) ->
  S - 9216 <= sp' - PMSR.OPNEW_SCR -> sp' <= S -> sp' mod 16 = 0 ->
  (forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (B : Z),
      getr R' (reg 10) = Z_to_bv 64 B -> (forall k, In k PMK.cs_all -> getr R' (reg k) = getr R (reg k)) ->
      L5C.fresh_block L LBc M' B 64 -> hi_heap HI ((B, 64) :: LBc) (debitR cr 64) M' (m_vmmaps model') ->
      model_but_vm model0 model' -> m_halted model' = None -> m_vm_lazy model' = [] -> mem_ok M' ->
      (forall a m, 0 <= m -> ((sp' <= a /\ a + m <= hl_sptop L) \/ (exists B0 n, In (B0, n) LBc /\ B0 <= a /\ a + m <= B0 + n)) -> L5C.agree_on M M' a m) ->
      L5.defined M' (sp' - PMSR.OPNEW_SCR) PMSR.OPNEW_SCR ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' r M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0xbe8b0 M model) K.
