(* [comment removed for export] *)
Definition dynfb (j b : Z) : Z := Z.lor (Z.land b 2) (Z.land ((((2 * (j / 2)) mod 2 ^ 64) + 1) mod 2 ^ 64) 253).
Lemma dynfb_ok j b : 0 <= j < 256 -> 0 <= b < 256 -> 0 <= dynfb j b <= 255 /\ Z.testbit (dynfb j b) 0 = true.
Proof.
