(* [comment removed for export] *)
Lemma carryT M M1 (P : Z -> Prop) (OWN : list (Z * Z)) model1 cr VM :
  ctxT M model1 -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ P a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  hi_heap HI (OWN ++ LB) cr M VM ->
  (forall a, P a -> (S - 9216 <= a < S - 192) \/ (S - 184 <= a < S - 88) \/ (exists B m, In (B, m) OWN /\ B <= a < B + m)) ->
