(* [comment removed for export] *)
Lemma callT (LBc : list (Z * Z)) (sp' scr : Z) M1 M3 model1 model3 :
  ctxT M1 model1 -> incl LB LBc -> PMFR.brange L LBc -> 0 <= scr -> S - 9216 <= sp' - scr -> sp' <= S - 192 ->
  L5C.hpres L LBc sp' scr [] M1 M3 -> model_but_vm model1 model3 ->
